// PAUK Automotive KI-Fahrzeugbewertung – Cloudflare Worker / Playground
// Benötigtes Secret im Worker: OPENAI_API_KEY
// Optional: OPENAI_VISION_MODEL (Standard: gpt-5.6-sol)

const HTML_B64 = "";
const RULES = [['L01','Lack','Oberflächlicher Kratzer','S1','Polieren / Finish',80,180],['L02','Lack','Kratzer, lokal begrenzt','S2','Smart Repair / Spot-Lackierung',180,400],['L03','Lack','Tiefer Kratzer bis Grundierung','S3','Bauteil lackieren',450,850],['K01','Karosserie','Kleine Parkdelle, Lack intakt','S1','Lackfreies Ausbeulen',120,300],['K02','Karosserie','Mittlere Delle','S2','Ausbeulen / Instandsetzen',300,650],['K03','Karosserie','Starke Delle mit Lackschaden','S3','Spengler + Lackierung',700,1600],['K04','Karosserie','Stark verformtes Anbauteil','S4','Ersetzen + Lackierung',1000,3000],['S01','Stoßfänger','Leichter Kratzer','S1','Polieren / Smart Repair',150,350],['S02','Stoßfänger','Tiefer Lackschaden','S2','Instandsetzen + Lackieren',400,800],['S03','Stoßfänger','Riss / Verformung','S3','Kunststoffreparatur + Lack',600,1200],['S04','Stoßfänger','Bruch / Austausch','S4','Ersetzen + Lack',900,2200],['F01','Felge','Leichter Bordsteinschaden','S1','Aufbereitung',100,200],['F02','Felge','Starker optischer Schaden','S2','Instandsetzung',180,350],['F04','Felge','Verformt / gerissen','S4','Austausch / technische Prüfung',300,1200],['R02','Reifen','Reparierbarer Einstich','S2','Fachgerechte Reparatur',40,80],['R04','Reifen','Seitenwand / Karkasse beschädigt','S4','Reifen ersetzen',120,450],['G01','Glas','Kleiner reparabler Steinschlag','S1','Harzreparatur',90,180],['G04','Glas','Windschutzscheibe gerissen','S4','Scheibentausch inkl. Einbau',600,1800],['B02','Beleuchtung','Scheinwerfer optisch beschädigt','S2','Aufbereitung / Reparatur',120,300],['B04','Beleuchtung','LED-/Matrix-Scheinwerfer defekt','S4','Austausch / ggf. Kalibrierung',800,3500],['A02','Außenspiegel','Gehäuse / Kappe beschädigt','S2','Reparatur / Lackierung',200,500],['A03','Außenspiegel','Kompletteinheit beschädigt','S3','Austausch',450,1500],['I01','Innenraum','Starke Verschmutzung','S1','Intensivaufbereitung',150,400],['I02','Innenraum','Sitzbezug beschädigt','S2','Smart Repair / Teilreparatur',200,600],['I03','Innenraum','Sitz stark beschädigt','S3','Bezug / Polster ersetzen',500,1500],['U02','Unterboden','Unterbodenverkleidung beschädigt','S2','Reparatur / Austausch',250,700],['FW4','Fahrwerk','Achs-/Lenkungsschaden','S4','Diagnose + Reparatur',800,3500],['AD3','ADAS','Kamera/Sensor nach Karosseriearbeit','S3','Kalibrierung',180,500]];
const RULE_MAP = Object.fromEntries(RULES.map(r => [r[0], r]));

function j(data,status=200){return new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}})}
function page(){const bin=atob(HTML_B64);const bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));return new Response(bytes,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store"}})}

async function health(env){
 const key=(env.OPENAI_API_KEY||'').trim();
 if(!key) return j({ok:false,stage:'environment',error:'OPENAI_API_KEY ist im Cloudflare Worker nicht gesetzt.'},500);
 if(!key.startsWith('sk-')) return j({ok:false,stage:'environment',error:'OPENAI_API_KEY hat kein gültiges Format.'},500);
 const model=(env.OPENAI_VISION_MODEL||'gpt-5.6-sol').trim();
 try{const r=await fetch('https://api.openai.com/v1/models/'+encodeURIComponent(model),{headers:{Authorization:'Bearer '+key}});const txt=await r.text();let d={};try{d=JSON.parse(txt)}catch{};if(!r.ok)return j({ok:false,stage:'openai',status:r.status,error:d?.error?.message||('OpenAI HTTP '+r.status),model},502);return j({ok:true,stage:'ready',model,message:'Cloudflare Worker und OpenAI API sind erreichbar.'})}catch(e){return j({ok:false,stage:'network',error:e?.message||'OpenAI-Verbindung fehlgeschlagen.',model},502)}
}

async function analyze(request,env){
 const key=(env.OPENAI_API_KEY||'').trim(); if(!key)return j({error:'OPENAI_API_KEY fehlt im Cloudflare Worker.'},500);
 try{
  const {images=[],vehicle={}}=await request.json(); if(images.length<8)return j({error:'Mindestens 8 Pflichtaufnahmen erforderlich.'},400);
  const table=RULES.map(r=>`${r[0]} | ${r[1]} | ${r[2]} | ${r[3]}`).join('\n');
  const content=[{type:'input_text',text:`Konservative Kfz-Schaden-Vorprüfung für PAUK Automotive. Melde nur tatsächlich sichtbare Schäden und erfinde nichts. Gleichen Schaden über mehrere Ansichten nur einmal melden. Ordne ausschließlich einer rule_id aus der Tabelle zu. Wenn nicht sicher zuordenbar: weglassen. S4 und sicherheitsrelevante Treffer immer requires_review=true. Verdeckte Schäden niemals aus Fotos ableiten. Confidence bei Reflexion, Schmutz, Schatten oder schlechter Perspektive reduzieren. Fahrzeug: ${JSON.stringify(vehicle)}\nRegeln:\n${table}`}];
  for(const im of images){content.push({type:'input_text',text:`Nächstes Foto: ${im.label} (${im.view})`});content.push({type:'input_image',image_url:im.data,detail:'high'})}
  const schema={type:'object',additionalProperties:false,required:['damages'],properties:{damages:{type:'array',items:{type:'object',additionalProperties:false,required:['rule_id','part','confidence','requires_review','reason'],properties:{rule_id:{type:'string',enum:RULES.map(x=>x[0])},part:{type:'string'},confidence:{type:'number',minimum:0,maximum:1},requires_review:{type:'boolean'},reason:{type:'string'}}}}}};
  const model=(env.OPENAI_VISION_MODEL||'gpt-5.6-sol').trim();
  const r=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({model,reasoning:{effort:'high'},input:[{role:'user',content}],text:{format:{type:'json_schema',name:'damage_assessment',strict:true,schema}}})});
  const raw=await r.json(); if(!r.ok)throw new Error(raw?.error?.message||('OpenAI API Fehler '+r.status));
  const t=raw.output_text||raw.output?.flatMap(x=>x.content||[]).find(x=>x.type==='output_text')?.text; if(!t)throw new Error('Keine strukturierte KI-Antwort erhalten.');
  const p=JSON.parse(t); const damages=(p.damages||[]).filter(d=>RULE_MAP[d.rule_id]&&d.confidence>=.55).map(d=>{const x=RULE_MAP[d.rule_id];return {...d,area:x[1],damage:x[2],level:x[3],action:x[4],min:x[5],max:x[6],requires_review:d.requires_review||x[3]==='S4'||d.confidence<.72}});
  return j({ok:true,damages,model});
 }catch(e){return j({error:e?.message||'Analyse fehlgeschlagen'},500)}
}

export default {
 async fetch(request,env){
  const u=new URL(request.url);
  if(u.pathname==='/health' && request.method==='GET') return health(env);
  if(u.pathname==='/analyze' && request.method==='POST') return analyze(request,env);
  if(u.pathname==='/' || u.pathname==='/index.html') return page();
  return new Response('Not found',{status:404});
 }
};
